# Try LD_PRELOAD trick: write a C library that dumps /proc/self/exe
c_code = r'''
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
__attribute__((constructor)) void dump(void) {
    // Try to open /proc/self/exe
    int fd = open("/proc/self/exe", O_RDONLY);
    if (fd < 0) {
        // Try opening ./executable
        fd = open("./executable", O_RDONLY);
        if (fd <0) {
            write(2, "open failed\n", 12);
            return;
        }
    }
    int out = open("/tmp/dumped", O_WRONLY|O_CREAT|O_TRUNC, 0755);
